# ---------------------------------------------------------------------------
# Pattern guidance blocks
# Injected into the developer prompt when task.pattern_refs contains
# the matching tag.  Keep each block concise — it's appended to the
# prompt verbatim.
# ---------------------------------------------------------------------------

PATTERN_GUIDANCE: dict[str, str] = {
    "Orchestrator-Worker": """
## Pattern: Orchestrator-Worker
Your code must implement a clear orchestrator node that:
- Maintains the task list and dispatches work to worker nodes.
- Does not perform domain work itself — it only routes and aggregates.
- Handles worker failure gracefully (catch exceptions, mark failed, continue).
Worker nodes must:
- Accept a well-defined input slice from the orchestrator.
- Return a well-defined result dict — no side effects on shared state.
""",

    "Plan-and-Execute": """
## Pattern: Plan-and-Execute
Your code must separate planning from execution:
- A planner function/node produces a structured plan (list of steps) before
  any execution begins.  The plan must be inspectable and serialisable.
- An executor function/node consumes the plan sequentially.
- The plan must be stored in state so the SQLite checkpointer can resume
  a partially-executed plan after a crash.
- Never mix planning logic into execution nodes.
""",

    "Reflection": """
## Pattern: Reflection
Your code must implement a self-critique loop:
- After initial generation, a critic node evaluates the output against
  explicit criteria (correctness, completeness, alignment with spec).
- The critic returns structured feedback: {passed: bool, issues: list[str]}.
- The generator iterates on feedback up to a configurable max_iterations.
- The loop must be bounded — always enforce max_iterations to prevent
  infinite cycles.
- Both the generator and critic prompts must be in the codebase as
  named constants, not inline strings.
""",

    "Tool-Use": """
## Pattern: Tool-Use
Your code must define tools as typed Python functions with:
- A clear docstring describing the tool's purpose and parameters
  (LangChain / OpenAI function calling uses these descriptions).
- Explicit input validation before any external call.
- A structured return type — never return raw strings from tools.
- Error handling that raises ToolException (not bare Exception) so the
  ToolNode can route failures correctly.
Tools must be registered in a tools list passed to the ToolNode.
""",

    "Evaluator-Optimizer": """
## Pattern: Evaluator-Optimizer
Your code must implement a generate → evaluate → refine loop:
- The evaluator must return a numeric score OR a structured verdict
  {score: float, passed: bool, feedback: str}.
- The optimizer uses the evaluator's feedback to produce an improved output.
- Loop termination condition: score >= threshold OR iteration >= max_iterations.
- Both threshold and max_iterations must come from config, not hardcoded.
""",

    "Human-in-the-Loop": """
## Pattern: Human-in-the-Loop
Your code must implement a proper HITL interrupt:
- Use LangGraph's interrupt_after to pause the graph at the review node.
- Push a structured approval_request payload over the HITL channel:
  {type: "approval_request", run_id: str, request_id: str, payload: dict}.
- Resume is triggered by an external approval_response — the graph must
  not poll or block a thread.
- Both WebSocket push and REST fallback (POST .../approve) must be wired.
- Store the pending request_id on the Run record so it survives a restart.
""",

    "RAG": """
## Pattern: RAG (Retrieval-Augmented Generation)
Your code must implement retrieval before generation:
- The retriever must be decoupled from the generator — it is a separate
  function/node that returns a list of Document objects.
- Retrieved chunks must be deduped and ranked by relevance score.
- The generator prompt must clearly delimit retrieved context from the
  user query (e.g. a CONTEXT: section before the QUESTION:).
- Never embed raw retrieved text directly into f-strings — always use
  a structured prompt template.
- Retrieval failures must be caught and surfaced as empty context, not
  as exceptions that crash the graph.
""",
}

# Planner output uses a few assignment/domain names that differ from the
# canonical prompt guidance names. Keep aliases explicit so generated tasks get
# the same instructions reviewers expect them to satisfy.
PATTERN_GUIDANCE["Planner-Executor"] = PATTERN_GUIDANCE["Plan-and-Execute"]
PATTERN_GUIDANCE["Critic-Refine"] = PATTERN_GUIDANCE["Reflection"]
PATTERN_GUIDANCE["Critic-Refine (Reflexion)"] = PATTERN_GUIDANCE["Reflection"]
PATTERN_GUIDANCE["Reflexion"] = PATTERN_GUIDANCE["Reflection"]
PATTERN_GUIDANCE["Router"] = """
## Pattern: Router
Your code must expose clear routing boundaries:
- FastAPI routes should be thin adapters that validate input, enforce auth /
  ownership, and delegate workflow behavior to service or graph functions.
- Route handlers must return stable response models and consistent HTTP errors.
- Workflow routing must use explicit conditional branches with exhaustive
  statuses instead of hidden fall-through behavior.
- Keep path/query/body parameters typed and avoid leaking internal exceptions.
"""

# Patterns that trigger a Reflection inner loop in the subgraph.
# build_developer_prompt() uses this to tell the developer a critic is coming.
REFLECTION_PATTERNS = {
    "Reflection",
    "Critic-Refine",
    "Critic-Refine (Reflexion)",
    "Reflexion",
}

# Patterns that require tool infrastructure in the subgraph.
TOOL_USE_PATTERNS = {"Tool-Use"}


def _workflow_pattern_checklist(pattern_refs: list[str]) -> str:
    """Return reviewer checks scoped to the patterns assigned to this task."""
    refs = set(pattern_refs or [])
    checks: list[str] = []

    if refs.intersection({"Orchestrator-Worker"}):
        checks.append("Orchestrator-Worker: verify a dispatch-only orchestrator and separate worker functions.")
    if refs.intersection({"Plan-and-Execute", "Planner-Executor"}):
        checks.append("Plan-and-Execute / Planner-Executor: verify planning is separated from execution for this task slice.")
    if refs.intersection(REFLECTION_PATTERNS):
        checks.append("Reflection / Critic-Refine: verify a bounded generate -> critique -> revise loop where this task owns revision behavior.")
    if refs.intersection(TOOL_USE_PATTERNS):
        checks.append("Tool-Use: verify tools are registered through a ToolNode or equivalent tool registry.")
    if refs.intersection({"Evaluator-Optimizer"}):
        checks.append("Evaluator-Optimizer: verify a structured evaluation gate and bounded optimization loop.")
    if refs.intersection({"Human-in-the-Loop"}):
        checks.append("Human-in-the-Loop: verify interrupt/resume semantics for the current approval or clarification slice.")
    if refs.intersection({"Router"}):
        checks.append("Router: verify route handlers validate inputs, delegate business logic, and return consistent errors.")
    if refs.intersection({"RAG"}):
        checks.append("RAG: verify retrieval is separate from generation and retrieved context is clearly delimited.")

    if not checks:
        return "No pattern-specific topology is required; review only basic coherence for the current task."
    return "\n".join(f"{idx}. {check}" for idx, check in enumerate(checks, start=1))


# ---------------------------------------------------------------------------
# Developer prompt
