def build_developer_prompt(
    *,
    task_title:           str,
    task_description:     str,
    pattern_refs:         list[str],
    requirements_context: str,
    architecture_context: str,
    existing_files:       Optional[list[str]] = None,
    critic_feedback:      Optional[str]       = None,
) -> list[dict]:
    """
    Build the system + user message list for the developer agent.

    Parameters
    ----------
    task_title / task_description
        From the current TaskRecord.

    pattern_refs
        Tags from task.pattern_refs.  Each recognised tag injects a
        PATTERN_GUIDANCE block into the prompt.

    requirements_context / architecture_context
        Full text of the requirements doc and architecture spec, loaded
        once at graph entry and passed through OrchestratorState.

    existing_files
        Relative paths of files already written in the workspace.
        Injected so the developer knows what exists and can import it
        rather than duplicating.

    critic_feedback
        When present, this is a Reflection-pattern iteration — the
        developer has seen a critic's assessment and must revise.

    Returns
    -------
    list[dict]  — OpenAI messages format: [{"role": ..., "content": ...}]
    """

    # -- Pattern guidance blocks ---------------------------------------------
    pattern_sections = []
    for tag in pattern_refs:
        guidance = PATTERN_GUIDANCE.get(tag)
        if guidance:
            pattern_sections.append(guidance.strip())

    pattern_block = "\n\n".join(pattern_sections) if pattern_sections else (
        "No specific patterns are required for this task — "
        "follow clean, idiomatic Python."
    )

    # -- Reflection awareness ------------------------------------------------
    has_reflection = bool(REFLECTION_PATTERNS.intersection(pattern_refs))
    reflection_note = (
        "\n\nNote: A critic agent will review your output before it reaches "
        "the human reviewers.  The critic checks alignment with the "
        "Reflection pattern requirements above.  Write code that is clean "
        "enough to pass that check on the first attempt — but do not let "
        "anticipated critic feedback prevent you from producing complete code."
    ) if has_reflection else ""

    # -- Existing workspace context ------------------------------------------
    if existing_files:
        files_list = "\n".join(f"  - {p}" for p in sorted(existing_files))
        workspace_block = (
            f"The following files have already been written to the workspace "
            f"by earlier tasks.  You may import from them:\n{files_list}"
        )
    else:
        workspace_block = (
            "The workspace is empty — this is the first task.  "
            "You may define shared utilities that later tasks will import."
        )

    # -- Critic feedback block (Reflection iterations only) ------------------
    critic_block = ""
    if critic_feedback:
        critic_block = f"""
---
## Critic Feedback — Revise Your Output

A critic has reviewed your previous attempt and raised the following issues.
You MUST address every point before producing your revised output:

{critic_feedback.strip()}
---
"""

    # -- System message ------------------------------------------------------
    system_message = {
        "role": "system",
        "content": (
            "You are an expert Python software engineer building a production-quality "
            "LangGraph / FastAPI application.  You write clean, well-documented, "
            "type-annotated Python 3.11+ code.\n\n"

            "## Output Format — STRICT\n"
            "You MUST output every file inside a <file> XML tag:\n\n"
            "    <file path=\"relative/path/to/module.py\">\n"
            "    # file content here\n"
            "    </file>\n\n"
            "Rules:\n"
            "- One <file> block per file.  Do not split a file across multiple blocks.\n"
            "- The path attribute is relative to the workspace root.  "
            "Use forward slashes.  No leading slash.\n"
            "- You may write multiple files.  Output them sequentially.\n"
            "- Text outside <file> tags is ignored by the parser.  "
            "You may use that space for brief reasoning, but keep it short.\n"
            "- Never truncate file content — output every line, even for long files.\n"
            "- Do not output placeholder comments like '# ... rest of code ...'  "
            "Every function must be fully implemented.\n\n"

            "## Code Quality Requirements\n"
            "- Full type annotations on all functions and class attributes.\n"
            "- Docstrings on every module, class, and public function.\n"
            "- No bare `except:` — always catch specific exception types.\n"
            "- No hardcoded secrets, connection strings, or credentials.  "
            "Use environment variables or settings objects.\n"
            "- No `print()` statements in production code — use the `logging` module.\n"
            "- Every async function that touches I/O must use `async/await` "
            "consistently — no `asyncio.run()` inside async functions.\n"
        ),
    }

    # -- User message --------------------------------------------------------
    user_message = {
        "role": "user",
        "content": f"""
# Task: {task_title}

## Description
{task_description.strip()}

## Pattern Requirements
{pattern_block}
{reflection_note}

## Requirements Document
<requirements>
{requirements_context.strip()}
</requirements>

## Architecture Specification
<architecture>
{architecture_context.strip()}
</architecture>

## Current Workspace State
{workspace_block}
{critic_block}
## Your Output
Write all files required to implement this task.
Use <file path="..."> blocks as instructed.
Begin now.
""".strip(),
    }

    return [system_message, user_message]


# ---------------------------------------------------------------------------
# Retry prompt (developer receives aggregated reviewer feedback)
# ---------------------------------------------------------------------------

def build_retry_prompt(
    *,
    task_title:           str,
    task_description:     str,
    pattern_refs:         list[str],
    requirements_context: str,
    architecture_context: str,
    developer_output:     str,
    aggregated_feedback:  str,
    retry_number:         int,
    max_retries:          int,
    existing_files:       Optional[list[str]] = None,
) -> list[dict]:
    """
    Build the message list for a retry iteration.

    This is separate from build_developer_prompt() because the framing
    is meaningfully different: the developer is revising existing output
    rather than starting from scratch, and needs to see both its previous
    attempt and the specific reviewer objections.

    The previous output is included in full so the model doesn't need to
    regenerate unchanged files — it can output only the files that need
    fixing.  The parser in nodes.py always takes the latest version of
    each path, so re-outputting unchanged files is also fine.
    """

    pattern_sections = []
    for tag in pattern_refs:
        guidance = PATTERN_GUIDANCE.get(tag)
        if guidance:
            pattern_sections.append(guidance.strip())
    pattern_block = "\n\n".join(pattern_sections) if pattern_sections else (
        "No specific patterns required — follow clean idiomatic Python."
    )

    if existing_files:
        files_list = "\n".join(f"  - {p}" for p in sorted(existing_files))
        workspace_block = f"Files already in workspace:\n{files_list}"
    else:
        workspace_block = "No other files in workspace yet."

    system_message = {
        "role": "system",
        "content": (
            "You are an expert Python software engineer revising code based on "
            "reviewer feedback.  Your task is to address every reviewer objection "
            "and re-output corrected files.\n\n"

            "## Output Format — STRICT (same as before)\n"
            "Output every revised file inside a <file path=\"...\"> block.\n"
            "You may re-output unchanged files — the parser takes the latest "
            "version of each path.\n"
            "Never truncate file content.  Never output placeholder comments.\n"
        ),
    }

    user_message = {
        "role": "user",
        "content": f"""
# Revision Attempt {retry_number} of {max_retries}
# Task: {task_title}

## What You Must Fix
The reviewers rejected your previous output.  
You MUST address every point below before re-submitting:

<reviewer_feedback>
{aggregated_feedback.strip()}
</reviewer_feedback>

## Your Previous Output (for reference)
<previous_output>
{developer_output.strip()}
</previous_output>

## Task Description (reminder)
{task_description.strip()}

## Pattern Requirements (reminder)
{pattern_block}

## Requirements Document
<requirements>
{requirements_context.strip()}
</requirements>

## Architecture Specification
<architecture>
{architecture_context.strip()}
</architecture>

## Current Workspace State
{workspace_block}

## Your Revised Output
Re-output all files that need changes (and any others you want to include).
Use <file path="..."> blocks.  Begin now.
""".strip(),
    }

    return [system_message, user_message]


# ---------------------------------------------------------------------------
# Critic prompt (Reflection pattern inner loop)
# ---------------------------------------------------------------------------

def build_critic_prompt(
    *,
    task_title:       str,
    task_description: str,
    pattern_refs:     list[str],
    developer_output: str,
) -> list[dict]:
    """
    Build the message list for the Reflection-pattern critic node.

    The critic runs BEFORE the human reviewers.  Its job is to catch
    structural issues — missing implementations, wrong pattern usage,
    obvious logic errors — so the human reviewers only see code that
    is at least structurally sound.

    The critic returns a JSON object, not prose:
        {
          "passed": bool,
          "issues": ["issue 1", "issue 2", ...],
          "feedback": "consolidated feedback string for the developer"
        }

    "passed": true means the critic is satisfied and the code should
    proceed to the human reviewers.  The issues list should be empty.
    "passed": false means the developer must revise.
    """

    pattern_names = ", ".join(pattern_refs) if pattern_refs else "none"

    system_message = {
        "role": "system",
        "content": (
            "You are a senior code reviewer performing an internal quality gate "
            "before human reviewers see the code.  You are thorough but fair — "
            "you do not invent problems that aren't there.\n\n"

            "## Your Output Format — STRICT\n"
            "Respond with ONLY a JSON object.  No preamble, no markdown fences:\n\n"
            '    {"passed": true, "issues": [], "feedback": ""}\n'
            "    or\n"
            '    {"passed": false, "issues": ["Missing input validation on X", ...], '
            '"feedback": "Consolidated feedback string for the developer."}\n\n'

            "Do not include any text outside the JSON object."
        ),
    }

    user_message = {
        "role": "user",
        "content": f"""
# Critic Review
# Task: {task_title}
# Required patterns: {pattern_names}

## Task Description
{task_description.strip()}

## Developer Output to Review
<developer_output>
{developer_output.strip()}
</developer_output>

## What to Check
1. **Completeness**: Are all files needed for this task present?
   Are all functions fully implemented (no stubs, no TODOs, no truncations)?

2. **Pattern compliance**: Does the code correctly implement each of the
   following patterns: {pattern_names}?
   Check structure, not style — missing orchestrator dispatch, unbounded
   loops, wrong node topology, etc. are blocking issues.

3. **Imports**: Do all import statements reference modules that either
   exist in the workspace or are standard library / known third-party packages?

4. **Obvious logic errors**: Division by zero, index out of bounds on
   guaranteed-empty lists, awaiting non-coroutines, etc.

5. **Type annotations**: Are all public function signatures annotated?

Do NOT flag style nits (variable names, comment density, minor formatting).
Focus on issues that would cause runtime failures or pattern misalignment.

Respond with your JSON verdict now.
""".strip(),
    }

    return [system_message, user_message]


