def build_workflow_reviewer_prompt(
    *,
    task_title:       str,
    task_description: str,
    pattern_refs:     list[str],
    developer_output: str,
    architecture_context: str,
) -> list[dict]:
    """
    Reviewer 1 — Workflow correctness.

    Checks that the generated agent orchestration matches the selected
    patterns and the architecture specification.  Does not review
    prompt quality or security — those are other reviewers' jobs.
    """

    pattern_names = ", ".join(pattern_refs) if pattern_refs else "none specified"
    required_pattern_checks = _workflow_pattern_checklist(pattern_refs)

    system_message = {
        "role": "system",
        "content": (
            f"{_REVIEWER_SYSTEM_BASE}\n\n"
            "## Your Specialisation: Workflow & Orchestration Correctness\n"
            "You check that the generated code correctly implements the required "
            "agentic patterns and matches the architecture spec.  You do NOT "
            "review prompt quality or security vulnerabilities."
        ),
    }

    user_message = {
        "role": "user",
        "content": f"""
# Workflow Review
# Task: {task_title}
# Required patterns: {pattern_names}

## Task Description
{task_description.strip()}

## Architecture Specification (source of truth)
<architecture>
{architecture_context.strip()}
</architecture>

## Generated Code to Review
<developer_output>
{developer_output.strip()}
</developer_output>

## Required Pattern Checks
{required_pattern_checks}

## What to Check
1. **Pattern topology**: Verify only the required pattern checks listed above.
   Do not require Reflection, Tool-Use, HITL, RAG, or any other pattern unless
   it appears in the Required patterns list for this task.

2. **Task-slice architecture alignment**: Does the implementation match the
   component, interface, or data flow owned by this task? Do not fail because
   components assigned to other tasks are absent.

3. **State management**: If this task defines graph state, is it typed and
   JSON-serialisable? If it does not define graph state, this check is advisory.

4. **Graph completeness**: If this task defines graph edges, are conditional
   branches exhaustive for this slice? If it does not define a graph, this is
   advisory rather than blocking.

5. **Checkpointer compatibility**: No SQLAlchemy objects or non-serialisable
   classes should be placed into LangGraph state when this task creates state.

Respond with your JSON verdict now.
""".strip(),
    }

    return [system_message, user_message]


def build_prompt_reviewer_prompt(
    *,
    task_title:       str,
    task_description: str,
    developer_output: str,
) -> list[dict]:
    """
    Reviewer 2 — Prompt quality.

    Checks generated prompts for clarity, role definition, and
    injection-resistance.  Only fires if the developer output contains
    prompt strings — if the task produced no prompts, the reviewer
    should return passed=True with an advisory note.
    """

    system_message = {
        "role": "system",
        "content": (
            f"{_REVIEWER_SYSTEM_BASE}\n\n"
            "## Your Specialisation: Prompt Quality & Injection Resistance\n"
            "You review LLM prompt strings defined in the generated code.  "
            "You do NOT review workflow structure or security vulnerabilities."
        ),
    }

    user_message = {
        "role": "user",
        "content": f"""
# Prompt Review
# Task: {task_title}

## Task Description
{task_description.strip()}

## Generated Code to Review
<developer_output>
{developer_output.strip()}
</developer_output>

## What to Check
If the generated code contains NO prompt strings (f-strings, string constants
assigned to prompt variables, messages lists), respond with:
{{"passed": true, "feedback": "No prompt strings found — not applicable.", "severity": "advisory"}}

Otherwise, for every prompt string found, check:

1. **Role definition**: Does the system message clearly define the agent's
   role, constraints, and output format?  A vague system message like
   "You are a helpful assistant" is a blocking issue for agent code.

2. **Output format instruction**: Does the prompt explicitly tell the model
   the required output format (JSON schema, XML tags, markdown structure)?
   Prompts that rely on the model "guessing" the format are blocking.

3. **Injection resistance**:
   - Is untrusted user input ever concatenated directly into a prompt
     without a clear delimiter (e.g. <user_input> tags)?
   - Is there a risk that user-supplied text could override system
     instructions?  (e.g. "Ignore previous instructions" attacks.)
   - Are retrieved document chunks clearly delimited from instructions?

4. **Clarity**: Would a different capable engineer understand the prompt's
   intent immediately?  Flag prompts that are ambiguous about what
   "good output" looks like.

5. **Hardcoded content**: Are prompt templates hardcoded as inline strings
   rather than named constants or template files?  Inline strings buried
   inside node functions are harder to maintain and test.

Respond with your JSON verdict now.
""".strip(),
    }

    return [system_message, user_message]


def build_security_reviewer_prompt(
    *,
    task_title:       str,
    task_description: str,
    developer_output: str,
) -> list[dict]:
    """
    Reviewer 3 — Security.

    Checks for OWASP basics: input validation, secrets handling,
    error leakage.  Scoped to what's realistic in LLM-generated
    application code — not a full pentest.
    """

    system_message = {
        "role": "system",
        "content": (
            f"{_REVIEWER_SYSTEM_BASE}\n\n"
            "## Your Specialisation: Security (OWASP Basics)\n"
            "You review generated code for common security issues relevant to "
            "FastAPI / LangGraph application code.  You do NOT review workflow "
            "structure or prompt quality."
        ),
    }

    user_message = {
        "role": "user",
        "content": f"""
# Security Review
# Task: {task_title}

## Task Description
{task_description.strip()}

## Generated Code to Review
<developer_output>
{developer_output.strip()}
</developer_output>

## What to Check

1. **Hardcoded secrets** (BLOCKING):
   - API keys, passwords, tokens, or connection strings hardcoded as
     string literals.
   - Any string matching common secret patterns:
     sk-..., Bearer ..., password=..., secret=... as literals.
   - Fix: must come from environment variables or a settings object.

2. **Input validation** (BLOCKING if missing on external inputs):
   - Treat strongly typed FastAPI parameters (`int`, UUID strings validated by
     Pydantic, enums, constrained fields) as valid input validation unless the
     value is later interpolated into a raw SQL string, shell command, or file
     path.
   - Treat SQLAlchemy ORM/parameterized database calls as SQL-injection safe;
     do not demand extra SQL sanitization for typed integer IDs.
   - FastAPI path/query/body parameters must use Pydantic models or
     explicit type annotations — no raw `request.body()` without parsing.
   - Any value used in a file path must be sanitised against path
     traversal (e.g. `../../../etc/passwd`).
   - Any value used in a shell command must be validated — no
     `subprocess.run(user_input, shell=True)`.

3. **Error leakage** (BLOCKING):
   - Exception handlers must not return raw stack traces or internal
     error messages to the API caller.
   - `except Exception as e: return {{"error": str(e)}}` patterns expose
     internals — must be caught and replaced with a generic message
     while logging the real error server-side.

4. **Sensitive data in logs** (ADVISORY unless obvious):
   - Logging full request bodies that may contain PII or credentials.
   - Logging LLM prompts that may contain retrieved document content.

5. **Insecure deserialization** (BLOCKING if present):
   - Use of `pickle.loads()` on untrusted data.
   - Use of `eval()` or `exec()` on any non-constant string.

6. **Dependency on unvalidated IDs** (BLOCKING):
   - `project_id` or `run_id` values from URL paths used directly in
     filesystem paths without sanitisation.  Must reject values
     containing `..`, `/`, or non-UUID characters.

If none of the above issues are present, respond with passed=true and
a brief "No issues found" feedback.

Respond with your JSON verdict now.
""".strip(),
    }

    return [system_message, user_message]


# ---------------------------------------------------------------------------
# Output parsers
# ---------------------------------------------------------------------------

# Matches <file path="some/path.py"> ... </file>
# re.DOTALL so content can span multiple lines.
_FILE_BLOCK_RE = re.compile(
    r'<file\s+path=["\']([^"\']+)["\']\s*>(.*?)</file>',
    re.DOTALL,
)


@dataclass
class ParsedFile:
    """
    A single file extracted from the developer agent's response.
    Mirrors GeneratedFile from state.py but lives here to avoid a
    circular import (parsers are used in nodes.py which also imports state).
    """
    relative_path: str
    content:       str


def parse_developer_output(raw_output: str) -> list[ParsedFile]:
    """
    Extract all <file path="..."> blocks from the developer agent response.

    Returns a list of ParsedFile instances in document order.
    Strips leading/trailing whitespace from each file's content.

    Raises ValueError if no file blocks are found — the developer node
    should treat this as a generation failure and retry.
    """
    matches = _FILE_BLOCK_RE.findall(raw_output)

    if not matches:
        raise ValueError(
            "Developer output contained no <file> blocks.  "
            "The model likely produced prose without following the output format.  "
            f"Raw output preview: {raw_output[:500]!r}"
        )

    # Deduplicate by path — last occurrence wins (model may revise a file
    # by outputting it again later in the same response).
    seen: dict[str, str] = {}
    for relative_path, content in matches:
        seen[relative_path.strip()] = content.strip()

    return [
        ParsedFile(relative_path=path, content=content)
        for path, content in seen.items()
    ]


@dataclass
class ParsedVerdict:
    """
    A reviewer's verdict extracted from their JSON response.
    Lives here for the same circular-import reason as ParsedFile.
    """
    passed:   bool
    feedback: str  = ""
    severity: str  = "blocking"


def parse_reviewer_verdict(
    raw_output: str,
    reviewer:   str,
) -> ParsedVerdict:
    """
    Parse a reviewer agent's JSON response into a ParsedVerdict.

    Handles two common model misbehaviours:
    1. JSON wrapped in a markdown fence (```json ... ```)
    2. Extra prose before or after the JSON object

    If parsing fails entirely, returns a blocking failure with the raw
    output as feedback — better to force a retry than silently pass.

    Parameters
    ----------
    raw_output : str
        The raw string returned by the reviewer LLM call.
    reviewer : str
        Reviewer identifier for error messages
        ("workflow_reviewer" | "prompt_reviewer" | "security_reviewer").
    """

    # Strip markdown fences if present
    cleaned = re.sub(r"```(?:json)?\s*", "", raw_output).strip()
    cleaned = cleaned.replace("```", "").strip()

    # Attempt to find the first {...} block in the output
    json_match = re.search(r'\{.*\}', cleaned, re.DOTALL)
    if not json_match:
        return ParsedVerdict(
            passed   = False,
            feedback = (
                f"{reviewer} returned a malformed response that could not be "
                f"parsed as JSON.  Raw output: {raw_output[:300]!r}"
            ),
            severity = "blocking",
        )

    try:
        data = json.loads(json_match.group())
    except json.JSONDecodeError as exc:
        return ParsedVerdict(
            passed   = False,
            feedback = (
                f"{reviewer} returned invalid JSON: {exc}.  "
                f"Raw output: {raw_output[:300]!r}"
            ),
            severity = "blocking",
        )

    return ParsedVerdict(
        passed   = bool(data.get("passed", False)),
        feedback = str(data.get("feedback", "")),
        severity = str(data.get("severity", "blocking")),
    )


def parse_critic_output(raw_output: str) -> tuple[bool, str]:
    """
    Parse the critic node's JSON response.

    Returns
    -------
    (passed, feedback)
        passed=True means the code is good enough to proceed to reviewers.
        feedback is the consolidated string to inject into the developer
        retry prompt if passed=False.
    """
    cleaned     = re.sub(r"```(?:json)?\s*", "", raw_output).strip().replace("```", "").strip()
    json_match  = re.search(r'\{.*\}', cleaned, re.DOTALL)

    if not json_match:
        # Treat parse failure as a pass — the critic is an inner gate,
        # not a hard blocker.  Log the issue but don't stall the pipeline.
        return True, ""

    try:
        data = json.loads(json_match.group())
    except json.JSONDecodeError:
        return True, ""

    passed   = bool(data.get("passed", True))
    issues   = data.get("issues", [])
    feedback = data.get("feedback", "")

    if not passed and not feedback and issues:
        feedback = "\n".join(f"- {issue}" for issue in issues)

    return passed, feedback
